'use strict';
throw new Error('该角色重绘动作页已撤下。当前预览使用用户原始 IP，请勿重新生成旧稿。');
const fs=require('node:fs'),path=require('node:path');const root=path.resolve(__dirname,'..');
const poses=[['welcome','举手迎接','1 秒 · 挥手两次与眨眼'],['observe','观察探索','1 秒 · 转头、移眼与指向'],['think','托腮思考','1.2 秒 · 手臂、点头与表情'],['celebrate','展示学习成果','1 秒 · 举手、微笑与点头']];
const layer=(name,cls='')=>`<img class="actor-part ${cls}" src="/miniprogram/assets/brand/actor/${name}.png" alt="">`;
function actor(p){return `<div class="actor actor-${p}" data-pose="${p}">${layer('body','actor-body')}<div class="actor-head">${layer('head')}${layer(p==='think'||p==='observe'?'eyes-think':p==='celebrate'?'eyes-happy':'eyes','actor-eyes')}${layer(p==='think'?'mouth-think':p==='celebrate'?'mouth-happy':'mouth','actor-mouth')}</div>${p!=='welcome'?layer('prop-'+p,'actor-prop'):''}${layer('arm-left-'+(p==='think'?'think':p==='celebrate'?'celebrate':'rest'),'actor-left')}${layer('arm-right-'+(p==='welcome'||p==='celebrate'?'wave':p==='observe'?'point':'rest'),'actor-right')}</div>`;}
const css=fs.readFileSync(path.join(root,'miniprogram/components/mascot-actor/index.wxss'),'utf8').replaceAll(':host','mascot-actor').replaceAll('image','img');
const html=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>智小谷 · 四组局部动作</title><style>*{box-sizing:border-box}body{margin:0;background:#eff7e9;color:#28523a;font:15px/1.7 -apple-system,"PingFang SC",sans-serif}header,footer{max-width:1100px;margin:auto;padding:30px}h1{margin:0 0 8px;font-size:28px}p{margin:0;color:#657665}a{color:#42835a}main{max-width:1100px;margin:auto;display:grid;grid-template-columns:repeat(4,1fr);gap:16px;padding:20px}section{padding:20px;background:white;border:1px solid #bdd4b4;border-radius:18px}h2{font-size:18px}button{min-height:44px;border:0;border-radius:12px;background:#42835a;color:white;font:inherit;padding:8px 16px;cursor:pointer}.stage{width:160px;height:190px;margin:30px auto 25px}.actor-part{object-fit:fill}.note{font-size:12px;color:#6b856b}.static{width:64px;height:76px;object-fit:contain}.source{display:block;font-size:13px;margin:8px 0}${css}@media(max-width:850px){main{grid-template-columns:repeat(2,1fr)}}@media(max-width:450px){main{grid-template-columns:1fr}}</style><header><h1>智小谷 · 四组局部动作</h1><p>同一二维角色，身体稳定；头部、表情、手臂与道具分别运动。游戏中按启用关卡顺序循环映射。</p><a href="/preview/反馈视觉对照-20261019.html">返回首页 A/B 对照</a></header><main>${poses.map(([p,label,note])=>`<section data-pose="${p}"><div class="stage">${actor(p)}</div><h2>${label}</h2><p>${note}</p><button data-play="${p}">播放${label}</button><a class="source" href="/miniprogram/assets/brand/actor/${p}.png">透明静态替代图</a><img class="static" src="/miniprogram/assets/brand/actor/${p}.png" alt="${label}静态图"></section>`).join('')}</main><footer><p>减少动态效果开启时保持静态。分层 SVG 与透明 PNG 位于交付目录 design-source/actor 和 miniprogram/assets/brand/actor。</p><p class="note">预览使用与原生组件相同的图层、关键帧和时长；不代表微信渲染或真机验收。</p></footer><script>const timers=new Set();document.querySelectorAll('[data-play]').forEach(button=>button.onclick=()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const actor=button.closest('section').querySelector('.actor');actor.classList.remove('is-playing');requestAnimationFrame(()=>requestAnimationFrame(()=>{actor.classList.add('is-playing');const timer=setTimeout(()=>{actor.classList.remove('is-playing');timers.delete(timer)},actor.dataset.pose==='think'?1200:1000);timers.add(timer)}));});document.addEventListener('visibilitychange',()=>{if(document.hidden){timers.forEach(clearTimeout);timers.clear();document.querySelectorAll('.is-playing').forEach(a=>a.classList.remove('is-playing'));}});</script></html>`;
fs.writeFileSync(path.join(root,'preview/角色动作预览-20261019.html'),html);console.log('Motion gallery built from actual component keyframes.');
